package com.project7.localmanager;
import android.content.*;import android.content.res.*;import android.system.Os;import java.io.*;import java.nio.file.*;import java.util.*;
/** Real original granters/calendar/spend/counters/writer; synthetic profiles. */
public final class BaiyeShopHost {
 static final long NOW=java.time.Instant.parse("2026-11-04T12:00:00Z").toEpochMilli();static final int[]IDS={8,157,158,478,480,540,595,617};
 static void check(boolean b,String s){BaiyeHost.check(b,s);}
 static byte[]profile(int gift,int crystals,int diamonds,int week){List<byte[]>items=new ArrayList<>();if(crystals>0){int first=Math.min(40,crystals);items.add(BaiyeHost.item(4253,first));if(crystals>first)items.add(BaiyeHost.item(4253,crystals-first));}return BsonLite.document("account",BaiyeHost.ACCOUNT,"an",BaiyeHost.ACCOUNT,"giftCoin",gift,"fyuanbao",diamonds,"dyuanbao",0,"level",99,"weeknum",BsonLite.document("w",week,"d",0),"inv",BsonLite.document("items",items),"ldd",BsonLite.document("opaque","preserve"),"unknown","preserve");}
 static byte[]longCallback(long value){byte[]base=BsonLite.document("store_id",8,"num",1,"coin_type",0,"ext",BsonLite.EMPTY_DOCUMENT);byte[]key="_cbid_".getBytes(java.nio.charset.StandardCharsets.UTF_8);int size=base.length+1+key.length+1+8;java.nio.ByteBuffer b=java.nio.ByteBuffer.allocate(size).order(java.nio.ByteOrder.LITTLE_ENDIAN);return b.putInt(size).put(base,4,base.length-5).put((byte)18).put(key).put((byte)0).putLong(value).put((byte)0).array();}
 static byte[]params(int id,int n){return BsonLite.document("store_id",id,"num",n,"source","card_main","coin_type",0,"ext",BsonLite.document("silence",false),"_cbid_",7);}
 static List<ProtoLite.EntityMessage>call(BaiyeHost.Disk d,int id,int n)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();check(BaiyeShopGateway.handleDirect(d.g,out,BaiyeHost.EID,BaiyeGateway.digest("buyCardMallItem"),params(id,n),BaiyeHost.ACCOUNT,null,null),"shop handled");List<ProtoLite.EntityMessage>r=BaiyeHost.frames(out.toByteArray());BaiyeHost.callback(r);return r;}
 static byte[]reply(List<ProtoLite.EntityMessage>r,String m){return BaiyeFragmentHost.reply(r,m);}
 static boolean success(List<ProtoLite.EntityMessage>r){return Boolean.TRUE.equals(BsonLite.boolValue(reply(r,"replyBuyCardMallItem"),"r"));}
 static void negative(BaiyeHost.Disk d,int id,int n)throws Exception{byte[]before=d.read();List<ProtoLite.EntityMessage>r=call(d,id,n);check(!success(r)&&Arrays.equals(before,d.read()),"shop rejection zero mutation");for(ProtoLite.EntityMessage m:r)check(!Arrays.equals(m.methodMd5,BaiyeGateway.digest("buyCardMallItemDone")),"negative has no done/reward");}
 static List<byte[]>items(byte[]profile){return LocalResourceEngine.array(BsonLite.arrayValue(BsonLite.documentValue(profile,"inv"),"items"));}
 static byte[]treasure(byte[]profile,int id){for(byte[]r:items(profile))if(Integer.valueOf(id).equals(BsonLite.intValue(r,"i"))&&BsonLite.documentValue(r,"tr")!=null)return r;throw new AssertionError("treasure not found");}
 static int count(byte[]profile,String key,int id)throws Exception{return BaiyeShopPolicy.counts(BsonLite.documentValue(BsonLite.documentValue(profile,"ldd"),key)).getOrDefault(id,0);}
 public static void main(String[]args)throws Exception{
  File assets=new File(args[0]);Context c=new Context(assets,new AssetManager(assets));CoreDrawPolicy.prepare(c);HistoryDrawPolicy.prepare(c);SelectorPolicy.prepare(c);OfflineMechanismGateway.prepare(c);BaiyeGateway.prepare(c);BaiyeShopGateway.prepare(c);LocalResourceCatalog resources=new LocalResourceCatalog(new FileInputStream(new File(assets,"resources.tsv")));Map<String,Object>cases=new LinkedHashMap<>();Set<String>newIds=new HashSet<>();
  for(int id:IDS){BaiyeShopCatalog.Product p=BaiyeShopCatalog.get(id);try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,profile(500,300,2000,2))){int writes=Os.renames;List<ProtoLite.EntityMessage>r=call(d,id,1);check(success(r)&&Os.renames==writes+1,"eight successful original-writer purchase "+id);byte[]after=d.read();check("preserve".equals(BsonLite.stringValue(after,"unknown")),"unknown preserved");for(String key:new String[]{"din","win","ton","mon"})check(count(after,key,id)==1,"all original counter domains");byte[]done=reply(r,"buyCardMallItemDone");check(new HashSet<>(BsonLite.keys(done)).equals(new HashSet<>(Arrays.asList("d","w","t","m","z","itemid","num","result","sd","silence"))),"exact original done keys");
    if(p.payment.equals("giftCoin")){check(BsonLite.intValue(after,"giftCoin")==500-p.cost,"giftCoin actual charge");reply(r,"updateGiftCoin");}else if(p.payment.equals("item"))check(BaiyeTransactions.count(after,4253)==300-p.cost,"original cross-stack item charge");else check(BsonLite.intValue(after,"fyuanbao")==2000-p.cost,"original yuanbao spend");
    if(p.kind.equals("treasure")){byte[]item=treasure(after,p.item),tr=BsonLite.documentValue(item,"tr");String u=BsonLite.uuidValue(item,"u");check(u!=null&&newIds.add(u)&&BsonLite.intValue(item,"w")==1,"fresh treasure UUID");check(BsonLite.intValue(tr,"cl")==3&&Arrays.equals(BsonLite.arrayValue(tr,"ft"),BsonLite.arrayValue(p.tr,"ft"))&&Arrays.equals(BsonLite.documentValue(tr,"attr"),BsonLite.documentValue(p.tr,"attr")),"exact designed tr/q preserved");}
    else check(BaiyeTransactions.count(after,p.item)==1,"real item grant");cases.put("done_"+id,BsonLite.messagePackValue(done,false));if(id==8){cases.put("callback",BsonLite.messagePackValue(r.get(r.size()-1).parameters,false));cases.put("gift",BsonLite.messagePackValue(reply(r,"updateGiftCoin"),false));}
   }
   try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,profile(0,0,0,2))){negative(d,id,1);}
  }
  for(int id:new int[]{157,158,617}){BaiyeShopCatalog.Product p=BaiyeShopCatalog.get(id);LocalResourceEngine.Result seed=new LocalResourceEngine.Result(profile(500,0,0,2));LocalResourceEngine.grant(seed,resources,"treasure",p.item,1,3,p.tr);byte[]held=treasure(seed.profile,p.item);
   for(boolean equipped:new boolean[]{false,true}){byte[]initial=seed.profile;if(equipped){initial=BsonLite.withProfileDocument(initial,"inv",BsonLite.document("items",Collections.emptyList()));initial=BsonLite.withProfileDocument(initial,"heromgr",BsonLite.document("hrs",Arrays.asList(Arrays.asList(7,BsonLite.document("ti",BsonLite.document("items",Arrays.asList(held)))))));}try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,initial)){List<ProtoLite.EntityMessage>r=call(d,id,1);check(success(r)&&BaiyeTransactions.count(d.read(),p.reget)==10,"actual inventory/equipped ownership reget "+id);if(equipped)check(items(d.read()).stream().noneMatch(v->Integer.valueOf(p.item).equals(BsonLite.intValue(v,"i"))),"no duplicate treasure over equipped");else check(BaiyeTransactions.count(d.read(),p.item)==1,"existing treasure retained");}}
  }
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,profile(100,0,1000,2))){check(success(call(d,8,50))&&BaiyeTransactions.count(d.read(),224)==50,"total50 batch allowed and stock bulk quantity exact");negative(d,8,1);negative(d,8,0);negative(d,540,Integer.MAX_VALUE);}
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,profile(0,0,1000,1))){negative(d,595,1);}
  byte[]p=profile(0,0,2000,2);LocalResourceEngine.Result seven=BaiyeShopPolicy.apply(p,resources,params(595,7),NOW);check(count(seven.profile,"win",595)==7,"weekly7");try{BaiyeShopPolicy.apply(seven.profile,resources,params(595,1),NOW);throw new AssertionError("weekly8");}catch(IllegalArgumentException expected){}try{BaiyeShopPolicy.apply(seven.profile,resources,params(595,1),NOW+86400000L);throw new AssertionError("same calendar week");}catch(IllegalArgumentException expected){}LocalResourceEngine.Result next=BaiyeShopPolicy.apply(seven.profile,resources,params(595,1),NOW+7*86400000L);check(count(next.profile,"win",595)==1&&count(next.profile,"ton",595)==8,"original calendar refresh independent story week");
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,profile(100,200,1000,2))){Os.failBefore=true;negative(d,8,1);Os.failAfter=true;check(success(call(d,8,1)),"postrename exact image success");ByteArrayOutputStream out=new ByteArrayOutputStream();check(!BaiyeShopGateway.handleDirect(d.g,out,BaiyeHost.EID,BaiyeGateway.digest("buyCardMallItem"),params(1934,1),BaiyeHost.ACCOUNT,null,null),"1934 original route");byte[]before=d.read();check(BaiyeShopGateway.handleRequest(d.g,out,BaiyeHost.EID,"buyCardMallItem",params(8,1),7,BaiyeHost.ACCOUNT,null,null),"reliable typed negative");check(Arrays.equals(before,d.read()),"reliable never charges");}
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,profile(100,200,1000,2))){
   for(Object invalid:new Object[]{"7",0,-1,7.0}){byte[]bad=BsonLite.document("store_id",8,"num",1,"source","card_main","coin_type",0,"ext",BsonLite.EMPTY_DOCUMENT,"_cbid_",invalid);byte[]before=d.read();int writes=Os.renames;ByteArrayOutputStream wire=new ByteArrayOutputStream();check(BaiyeShopGateway.handleDirect(d.g,wire,BaiyeHost.EID,BaiyeGateway.digest("buyCardMallItem"),bad,BaiyeHost.ACCOUNT,null,null),"invalid callback consumed safely");List<ProtoLite.EntityMessage>frames=BaiyeHost.frames(wire.toByteArray());check(!success(frames)&&Arrays.equals(before,d.read())&&Os.renames==writes,"invalid callback no mutation/write");for(ProtoLite.EntityMessage frame:frames)check(!Arrays.equals(frame.methodMd5,BaiyeGateway.digest("serverCallbackCarrier")),"never invent carrier for invalid id");}
  }
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,profile(100,200,1000,2))){byte[]before=d.read();int writes=Os.renames;ByteArrayOutputStream wire=new ByteArrayOutputStream();BaiyeShopGateway.handleDirect(d.g,wire,BaiyeHost.EID,BaiyeGateway.digest("buyCardMallItem"),longCallback(2147483648L),BaiyeHost.ACCOUNT,null,null);check(!success(BaiyeHost.frames(wire.toByteArray()))&&Arrays.equals(before,d.read())&&Os.renames==writes,"int64 callback overflow before mutation");wire.reset();BaiyeShopGateway.handleDirect(d.g,wire,BaiyeHost.EID,BaiyeGateway.digest("buyCardMallItem"),longCallback(7),BaiyeHost.ACCOUNT,null,null);check(success(BaiyeHost.frames(wire.toByteArray())),"positive int64 callback accepted");BaiyeHost.callback(BaiyeHost.frames(wire.toByteArray()));}
  Files.write(Paths.get(args[1]),new org.json.JSONObject(cases).toString(2).getBytes("UTF-8"));System.out.println("PASS8 actual shop transactions: item/giftCoin/yuanbao, original designed UUIDs and equipped reget, calendar counters, atomic faults, stock1934/reliable guards");
 }
}
